'use strict';

// MODULES //

var Uint32Array = require( '@stdlib/array/uint32' );
var zeroTo = require( '@stdlib/array/zero-to' );
var bench = require( '@stdlib/bench' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var rightShift = require( './../lib' );


// VARIABLES //

var options = {
	'dtype': 'uint32'
};


// MAIN //

bench( pkg, function benchmark( b ) {
	var shifts;
	var values;
	var out;
	var N;
	var M;
	var x;
	var i;

	N = 100;
	x = discreteUniform( N, 0, UINT32_MAX, options );
	values = [];
	for ( i = 0; i < N; i++ ) {
		values.push( Uint64.of( x[ i ], x[ (i+1)%N ] ) );
	}

	shifts = zeroTo( 64, 'uint32' );
	M = shifts.length;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = rightShift( values[ i%N ], shifts[ i%M ] );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !( out instanceof Uint64 ) ) {
		b.fail( 'should return a Uint64 instance' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s:assign', pkg ), function benchmark( b ) {
	var shifts;
	var out;
	var N;
	var M;
	var x;
	var i;

	N = 100;
	x = discreteUniform( N, 0, UINT32_MAX, options );
	shifts = zeroTo( 64, 'uint32' );
	M = shifts.length;

	out = new Uint32Array( 2 );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = rightShift.assign( x[ i%N ], x[ (i+1)%N ], shifts[ i%M ], out, 1, 0 ); // eslint-disable-line max-len
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !( out instanceof Uint32Array ) ) {
		b.fail( 'should return a Uint32Array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s:strided', pkg ), function benchmark( b ) {
	var shifts;
	var out;
	var N;
	var M;
	var x;
	var i;
	var j;

	N = 50;
	x = discreteUniform( N*2, 0, UINT32_MAX, options );
	shifts = zeroTo( 64, 'uint32' );
	M = shifts.length;

	out = new Uint32Array( 2 );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		j = ( i % N ) * 2;
		out = rightShift.strided( x, 1, j, shifts[ i%M ], out, 1, 0 );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !( out instanceof Uint32Array ) ) {
		b.fail( 'should return a Uint32Array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
